-- IPA 2022-07-24 management and strategy, checked against official key.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2022-20220724-q58','exam-fe','システム監査','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問58・改編】アクセス制御を監査するシステム監査人の行為として適切なものはどれか。','[{"id":"a","text":"ソフトウェアのアクセス制御台帳を作成・保管する"},{"id":"b","text":"データのアクセス制御に関する管理規程を閲覧する"},{"id":"c","text":"ネットワークのアクセス制御方針を制定する"},{"id":"d","text":"ハードウェアのアクセス制御の運用手続きを実施する"}]','"b"','監査人は規程や記録を確認し統制を評価する。統制の制定や運用そのものは被監査部門の役割。中文：审计人员检查管理规定，而不代替业务部门制定和执行控制。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20220724-q63','exam-fe','ビッグデータ','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問63・改編】マーケティングで活用するビッグデータの取扱いとして適切なものはどれか。','[{"id":"a","text":"不特定多数のソーシャルメディア上の意見は処理対象にしない"},{"id":"b","text":"蓄積された静的データに加え、Webアクセス履歴などリアルタイム性の高いデータも扱う"},{"id":"c","text":"必ず全体から無作為に一部だけを抽出して分析する"},{"id":"d","text":"音声や画像などの非構造化データは処理対象にしない"}]','"b"','ビッグデータには多様な形式と生成速度の情報が含まれる。中文：大数据可包含静态数据与实时访问记录，也可处理非结构化信息。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20220724-q64','exam-fe','プライバシーバイデザイン','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問64・改編】システム開発の上流段階で個人情報漏えいや目的外利用のリスクに対する予防機能を検討し組み込む考え方はどれか。','[{"id":"a","text":"情報セキュリティ方針"},{"id":"b","text":"セキュリティレベル"},{"id":"c","text":"プライバシーバイデザイン"},{"id":"d","text":"プライバシーマーク"}]','"c"','設計段階からプライバシー保護を考慮する。中文：隐私设计将隐私保护从系统设计初期纳入。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20220724-q68','exam-fe','コモディティ化','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問68・改編】コモディティ化の説明はどれか。','[{"id":"a","text":"革新的な新製品を市場に投入する"},{"id":"b","text":"技術革新で後発製品が先発製品の市場を衰退させる"},{"id":"c","text":"技術の成熟などにより他社製品との差別化が価格以外で難しくなる"},{"id":"d","text":"価格競争を避けるため他社とは異なる機能を開発する"}]','"c"','製品間の機能差が小さくなり、価格以外の差別化が難しくなる。中文：商品同质化使产品难以在价格以外形成差异。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20220724-q69','exam-fe','マーケティングミックス','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問69・改編】マーケティングミックスの説明はどれか。','[{"id":"a","text":"顧客市場を細分化し対象市場を選ぶ"},{"id":"b","text":"成長率と相対的市場シェアで事業の位置付けを分析する"},{"id":"c","text":"製品、価格、販売チャネル、プロモーションを組み合わせて効果的に販売する"},{"id":"d","text":"製品ライフサイクルの各段階で施策を選ぶ"}]','"c"','製品・価格・流通・販促などの施策を組み合わせる。中文：营销组合统筹产品、价格、渠道和促销。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20220724-q70','exam-fe','PLM','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問70・改編】PLMの目的はどれか。','[{"id":"a","text":"設備や倉庫を統合し多品種少量生産を自動化する"},{"id":"b","text":"製品開発から製造、販売、保守、リサイクルまでの情報を一元管理し競争力向上やコスト低減を図る"},{"id":"c","text":"生産計画から必要資材と発注時期を算出する"},{"id":"d","text":"部品供給から販売まで情報交換し在庫とリードタイムを減らす"}]','"b"','製品ライフサイクル全体の情報を管理する。中文：产品生命周期管理贯通研发、生产、销售、维护和回收的信息。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20220724-q71','exam-fe','生産計画','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問71・改編】生産計画数＝販売計画数＋在庫計画数−繰越在庫数。4月2日の在庫計画は250個、4月3日の販売計画4800個・在庫計画300個。4月3日の生産計画は何個か。','[{"id":"a","text":"4450"},{"id":"b","text":"4550"},{"id":"c","text":"4850"},{"id":"d","text":"4900"}]','"c"','4月3日の繰越在庫は前日の250個。4800＋300−250＝4850個。中文：以前日计划库存250为期初，计划生产4850件。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20220724-q73','exam-fe','行動ターゲティング','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問73・改編】インターネット広告における行動ターゲティングの説明はどれか。','[{"id":"a","text":"入力した検索キーワードに関連する広告を表示する"},{"id":"b","text":"表示中のWebページの内容に関連する広告を表示する"},{"id":"c","text":"現在地に基づき近隣施設の広告を表示する"},{"id":"d","text":"閲覧・検索・購買の履歴から興味を分析して関連広告を表示する"}]','"d"','利用者の行動履歴から関心を推定し広告を配信する。中文：行为定向广告根据浏览、搜索和购买等历史推测兴趣。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20220724-q74','exam-fe','HEMS','standard','single_choice','【IPA 2022年度 修了認定試験 2022-07-24 問74・改編】HEMSの説明として適切なものはどれか。','[{"id":"a","text":"発電した電気を家庭で使えるよう変換する"},{"id":"b","text":"廃家電の有用な部分をリサイクルする"},{"id":"c","text":"ヒートポンプを用いる電気給湯システム"},{"id":"d","text":"複数の家電をネットワークでつなぎ電力を可視化し消費を最適制御する"}]','"d"','HEMSは家庭のエネルギー消費を見える化し最適化する。中文：家庭能源管理系统连接家电，监控并优化用电。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220724_FE.pdf','ja','A','explicit','standard','fe_exemption');
